using System;
using System.Collections.Generic;
using System.IO;
using System.Reflection;
namespace Downfield {
public static class HardModeTests {
 public class Result {public int TD,First,Sacks,Picks,Catches,Huge;public float Yards;}
 public static void Steer(Simulation s,int frame,out float x,out float z){x=0;z=1;if(s.HandoffPending)return;Player runner=s.Controlled;float best=-999;for(int dir=-3;dir<=3;dir++){float dx=(float)Math.Sin(dir*.38),dz=(float)Math.Cos(dir*.38),gap=15;foreach(Player d in s.Players)if(d.Team==1&&d.Active&&d.KnockTime<=0&&d.Blocked<=0){float distance=Simulation.Distance(runner.X+dx*runner.Speed*.55f,runner.Z+dz*runner.Speed*.55f,d.X+d.VX*.22f,d.Z+d.VZ*.22f);gap=Math.Min(gap,distance);}float score=dz*1.4f+Math.Min(6,gap)*.8f-Math.Abs(dx-runner.VX/Math.Max(1,runner.Speed))*.18f;if(Math.Abs(runner.X+dx*4)>24.5f)score-=8;if(score>best){best=score;x=dx;z=dz;}}}
 public static Result Trial(int difficulty,int attack,int count){Franchise f=DefenseBalanceTests.Club(95);Result result=new Result();for(int seed=0;seed<count;seed++){foreach(ClubPlayer p in f.Players)p.InjuryWeeks=0;Simulation s=new Simulation(94000+seed);s.Difficulty=difficulty;f.Apply(s,1+seed%11);s.Playbook=attack==0?23:attack==1?10:attack==2?0:14;s.RunPlay=attack<2;s.NewGame();s.Snap();for(int frame=0;frame<1320&&(s.State==Phase.Live||s.State==Phase.Flight||s.State==Phase.Loose);frame++){float x,z;Steer(s,frame,out x,out z);s.Sprint=true;if(s.CanThrow&&attack>=2){x=s.Controlled.X<14?1:0;z=s.Controlled.Z<s.Spot-1?.18f:0;if(frame>=(attack==2?55:95)){s.BeginPass(DefenseBalanceTests.OpenReceiver(s));s.Charge=.35f;s.ReleasePass();}}if(!s.CanThrow&&!s.HandoffPending&&frame%36==0&&s.Controlled.Z>s.Spot){float gap=99;foreach(Player d in s.Players)if(d.Team==1&&d.Active&&d.KnockTime<=0)gap=Math.Min(gap,Simulation.Distance(s.Controlled.X,s.Controlled.Z,d.X,d.Z));if(gap<3.2f)s.SkillMove(x<0?-1:1,0);}s.Update(1f/60,x,z);}result.TD+=s.Touchdowns>0?1:0;result.First+=s.Touchdowns>0||s.TotalYards>=10?1:0;result.Yards+=s.Touchdowns>0?80:s.TotalYards;result.Sacks+=s.Sacks;result.Picks+=s.Interceptions;result.Catches+=s.Completions;result.Huge+=s.SpectacularHits;}Console.WriteLine("Adaptive attack / difficulty "+difficulty+" / attack "+attack+": TD "+result.TD+"/"+count+", first "+result.First+", yards "+(result.Yards/count).ToString("F1")+", sacks "+result.Sacks+", picks "+result.Picks+", huge "+result.Huge);return result;}
 public static int Run(){int checks=0,failures=0;Action<bool,string> check=(ok,n)=>{checks++;if(!ok){failures++;Console.WriteLine("FAIL Hard modes: "+n);}};
  for(int attack=0;attack<4;attack++){Result normal=Trial(1,attack,60),extreme=Trial(3,attack,60),super=Trial(4,attack,60);check(extreme.TD<=Math.Max(3,normal.TD/2)&&extreme.Yards<normal.Yards*.85f,"Extreme contains adaptive attack "+attack);check(super.TD<=1&&super.First<15&&super.Yards<=extreme.Yards+60,"SPRXTRM resists adaptive attack "+attack);if(attack<2)check(super.Huge>=35,"SPRXTRM produces brutal actual contacts / "+attack);}
  int penetrated=0,quick=0;bool physical=true,boost=true;for(int seed=0;seed<60;seed++){Simulation s=new Simulation(98000+seed);s.Difficulty=4;Franchise f=DefenseBalanceTests.Club(99);f.Apply(s,1+seed%11);s.NewGame();foreach(Player d in s.Players)if(d.Team==1)boost&=d.OVR==99&&d.Power==99;s.Snap();bool pressure=false;for(int frame=0;frame<180&&s.State==Phase.Live;frame++){foreach(Player d in s.Players){d.OldX=d.X;d.OldZ=d.Z;}s.Update(1f/60,0,0);foreach(Player d in s.Players)if(d.Team==1&&d.Role=="DL"&&d.Z<s.Spot-1)pressure=true;foreach(Player d in s.Players)if(d.Team==1&&d.KnockTime<=0)physical&=Simulation.Distance(d.X,d.Z,d.OldX,d.OldZ)<.8f;}if(pressure)penetrated++;if(s.Sacks>0)quick++;}Console.WriteLine("SPRXTRM pocket: penetration "+penetrated+"/60, sacks "+quick+"/60");check(penetrated>=58&&quick>=55,"elite blocking cannot sustain a stationary SPRXTRM pocket");check(physical&&boost,"SPRXTRM has explicit maximum defense and bounded physical movement");
  Console.WriteLine("Hard modes: "+checks+" checks, "+failures+" failures");return failures;
 }
}
}
